<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';
try{$login=valid_login((string)($_GET['login']??''));$cfg=addon_config();$nas=(string)($cfg['nas_ip']??'10.255.255.200');$db=db();$st=$db->prepare("SELECT r.username,r.framedipaddress,r.callingstationid,r.nasportid,r.acctstarttime,r.acctupdatetime,r.acctsessiontime,r.acctinputoctets,r.acctoutputoctets,c.uuid_cliente,c.nome,c.plano,c.ramal,c.cli_ativado,c.bloqueado,c.contrato FROM radacct r LEFT JOIN sis_cliente c ON LOWER(c.login)=LOWER(r.username) WHERE r.nasipaddress=? AND r.acctstoptime IS NULL AND LOWER(r.username)=LOWER(?) ORDER BY r.radacctid DESC LIMIT 1");$st->bind_param('ss',$nas,$login);$st->execute();$r=$st->get_result()->fetch_assoc();if(!$r)json_response(['ok'=>false,'error'=>'Cliente não está online no Huawei.'],404);json_response(['ok'=>true,'client'=>$r]);}catch(Throwable $e){json_response(['ok'=>false,'error'=>$e->getMessage()],400);}
